<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$days=max(1,min(30,(int)($_GET['days']??7)));
$rows=$pdo->query("SELECT l.id,u.name,u.username,u.class_name,b.title,c.code,l.loan_date,l.due_date,DATEDIFF(l.due_date,CURDATE()) days_left
FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id
WHERE l.returned_at IS NULL AND l.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL ".$days." DAY)
ORDER BY l.due_date,l.id")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Jatuh Tempo - Perpustakaan SMPIT</title><link rel=stylesheet href="../public/style.css"></head><body><div class="layout"><?php include '../public/nav.php';?><main class="main"><h1>⏰ Peminjaman Segera Jatuh Tempo</h1><div class="card" style="margin-bottom:16px"><form class="search"><label style="padding-top:9px">Tampilkan dalam</label><select name="days" onchange="this.form.submit()" style="max-width:180px;margin:0"><option value="3" <?=$days===3?'selected':''?>>3 hari</option><option value="7" <?=$days===7?'selected':''?>>7 hari</option><option value="14" <?=$days===14?'selected':''?>>14 hari</option><option value="30" <?=$days===30?'selected':''?>>30 hari</option></select></form></div><div class="cards"><div class="card"><small>Akan jatuh tempo</small><div class="num"><?=count($rows)?></div><small>transaksi</small></div><div class="card"><small>Hari ini</small><div class="num"><?=count(array_filter($rows,fn($r)=>(int)$r['days_left']===0))?></div><small>harus dikembalikan</small></div></div><br><div class="table-wrap"><table class="table"><tr><th>Anggota</th><th>Buku</th><th>Pinjam</th><th>Jatuh Tempo</th><th>Sisa</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><br><small><?=e($r['username'])?> · <?=e($r['class_name']??'-')?></small></td><td><?=e($r['title'])?><br><small><?=e($r['code'])?></small></td><td><?=e($r['loan_date'])?></td><td><?=e($r['due_date'])?></td><td><b style="color:<?=((int)$r['days_left']===0)?'#dc2626':'#d97706'?>"><?=((int)$r['days_left']===0)?'Hari ini':$r['days_left'].' hari'?></b></td><td><a class="btn" href="returns.php?copy_code=<?=urlencode($r['code'])?>">Proses Pengembalian</a></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6">✅ Tidak ada peminjaman yang jatuh tempo dalam periode ini.</td></tr><?php endif?></table></div></main></div></body></html>